function getAfipPuntosVenta(customPdv) {
	const num = Number(customPdv);
	if (!num || isNaN(num) || num <= 0) return AFIP_PUNTOS_VENTA;
	if (AFIP_PUNTOS_VENTA.some((p) => p.id === num)) return [AFIP_PUNTOS_VENTA.find((p) => p.id === num), ...AFIP_PUNTOS_VENTA.filter((p) => p.id !== num)];
	return [{
		id: num,
		nombre: `${String(num).padStart(5, "0")} - Punto de Venta Web Services ARCA / AFIP (WSFEv1)`,
		tipo: "WebService (WSFEv1)",
		bloqueado: false
	}, ...AFIP_PUNTOS_VENTA];
}
/**
* Algoritmo Oficial AFIP Módulo 11 para cálculo del Dígito Verificador (DV)
*/
function calcularDvCuit(cuitPrefixDni) {
	const clean = cuitPrefixDni.replace(/\D/g, "");
	if (clean.length < 10) return 0;
	const mult = [
		5,
		4,
		3,
		2,
		7,
		6,
		5,
		4,
		3,
		2
	];
	let sum = 0;
	for (let i = 0; i < 10; i++) sum += parseInt(clean[i], 10) * mult[i];
	const resto = sum % 11;
	if (resto === 0) return 0;
	if (resto === 1) return 9;
	return 11 - resto;
}
/**
* Calcula el CUIT/CUIL a partir de un DNI argentino de 7 u 8 dígitos
*/
function calcularCuilDesdeDni(dni, sexo = "M") {
	const cleanDni = dni.replace(/\D/g, "").padStart(8, "0").slice(-8);
	const prefix = sexo === "F" ? "27" : "20";
	return `${prefix}-${cleanDni}-${calcularDvCuit(`${prefix}${cleanDni}`)}`;
}
