				const result = {
					cuit: serverData.cuit || formattedCuit,
					cuil: serverData.cuil,
					dni: serverData.dni,
					razonSocial: serverData.razonSocial || "",
					nombreFantasia: serverData.nombreFantasia,
					condicionIva: serverData.condicionIva || "Consumidor Final",
					tipoDoc: serverData.tipoDoc || "CUIT",
					domicilioFiscal: serverData.domicilioFiscal || "",
					localidad: serverData.localidad || "Río Cuarto",
					provincia: serverData.provincia || "Córdoba",
					actividadPrincipal: serverData.actividadPrincipal || "Actividad comercial",
					estadoClave: serverData.estadoClave || "ACTIVO",
					origenDato: serverData.origenDato || "padron_oficial",
					requiereEdicion: serverData.requiereEdicion
				};
