	if (invoice.receptorTipoDoc === "CUIT") tipoDocRec = 80;
	else if (invoice.receptorTipoDoc === "CUIL") tipoDocRec = 86;
	else if (invoice.receptorTipoDoc === "DNI") tipoDocRec = 96;
	const qrObj = {
		ver: 1,
		fecha: invoice.fecha,
		cuit: cleanCuitEmisor,
		ptoVta: invoice.puntoVenta,
		tipoCmp: invoice.tipoComprobanteCodigo,
		nroCmp: invoice.numeroComprobante,
		importe: Math.round(invoice.total * 100) / 100,
		moneda: "PES",
		ctz: 1,
		tipoDocRec,
		nroDocRec: cleanReceptorDoc,
		tipoCodAut: "E",
		codAut: parseInt(invoice.cae, 10) || 74182940182914
	};
	const jsonStr = JSON.stringify(qrObj);
	const payloadBase64 = typeof window !== "undefined" ? btoa(unescape(encodeURIComponent(jsonStr))) : "";
