/**
* Genera código de barras AFIP de 40 dígitos
*/
function generarCodigoBarrasAfip(cuitEmisor, tipoCmpCodigo, puntoVenta, cae, vtoCae) {
	const base = `${cuitEmisor.replace(/\D/g, "").padStart(11, "0").slice(0, 11)}${String(tipoCmpCodigo).padStart(3, "0")}${String(puntoVenta).padStart(5, "0")}${cae.replace(/\D/g, "").padStart(14, "0").slice(0, 14)}${vtoCae.replace(/\D/g, "").padStart(8, "0").slice(0, 8)}`;
	let sumaPares = 0;
	let sumaImpares = 0;
	for (let i = 0; i < base.length; i++) {
		const digit = parseInt(base[i], 10);
		if ((i + 1) % 2 === 0) sumaPares += digit;
		else sumaImpares += digit;
	}
	return `${base}${(10 - (sumaImpares * 3 + sumaPares) % 10) % 10}`;
}
