function getCloudMasterBaseUrl() {
	if (typeof window === "undefined") return CLOUD_MASTER_SERVER_URL;
	if (isRunningOnLocalNetworkHost()) return CLOUD_MASTER_SERVER_URL;
	return window.location.origin;
}
function getDownloadEndpointUrl(pathWithLeadingSlash) {
	return `${getCloudMasterBaseUrl().replace(/\/$/, "")}${pathWithLeadingSlash.startsWith("/") ? pathWithLeadingSlash : `/${pathWithLeadingSlash}`}`;
}
