	const [tipoComprobante, setTipoComprobante] = (0, import_react.useState)(config.afipConfig?.tipoFactura === "C" ? "FC" : "FB");
	const [receptorTipoDoc, setReceptorTipoDoc] = (0, import_react.useState)("DNI");
