/**
* Aplica un acuerdo paritario oficial automáticamente sobre las escalas del convenio
* y sobre todos los legajos activos asignados, respetando el 50% en Media Jornada (Art. 92 TER).
*/
function aplicarAcuerdoParitarioOficial(acuerdo, convenios, legajos, config) {
	const factor = 1 + acuerdo.porcentajeAumento / 100;
	const targetConv = convenios.find((c) => c.id === acuerdo.convenioId || c.codigoCCT === acuerdo.codigoCCT) || convenios[0];
	const nuevasCategorias = targetConv.categorias.map((cat) => {
		const nuevoBasico = Math.round(cat.basico * factor);
		const nuevoNoRemun = acuerdo.sumaNoRemunerativa || cat.noRemunerativo || 12e4;
		return {
			...cat,
			basico: nuevoBasico,
			noRemunerativo: nuevoNoRemun,
			totalConformado: nuevoBasico + nuevoNoRemun
		};
	});
	const nuevoHistorialItem = {
		id: acuerdo.id,
		fecha: (/* @__PURE__ */ new Date()).toLocaleDateString("es-AR"),
		descripcion: `${acuerdo.titulo} (+${acuerdo.porcentajeAumento}%)`,
		porcentajeAumento: acuerdo.porcentajeAumento,
		sumaNoRemunerativa: acuerdo.sumaNoRemunerativa,
		resolucionHomologacion: acuerdo.resolucionHomologacion,
		aplicado: true
	};
	const nuevoConvenio = {
		...targetConv,
		paritariasVigentes: `${acuerdo.titulo} (${acuerdo.resolucionHomologacion})`,
		fechaActualizacion: (/* @__PURE__ */ new Date()).toLocaleDateString("es-AR"),
		sumaFijaNoRemunerativaVigente: acuerdo.sumaNoRemunerativa,
		resolucionHomologacion: acuerdo.resolucionHomologacion,
		categorias: nuevasCategorias,
		historialParitarias: [nuevoHistorialItem, ...targetConv.historialParitarias.filter((h) => h.id !== acuerdo.id)]
	};
	const nuevosConvenios = convenios.map((c) => c.id === targetConv.id ? nuevoConvenio : c);
	const sueldosPrevios = [];
	let legajosAfectados = 0;
	return {
		nuevosConvenios,
		nuevosLegajos: legajos.map((leg) => {
			if (!(leg.convenioId === targetConv.id || leg.convenio.includes(targetConv.codigoCCT) || leg.convenio.includes("130/75"))) return leg;
			const catNueva = nuevasCategorias.find((cat) => cat.id === leg.categoriaId || cat.nombre.toLowerCase() === leg.categoria.toLowerCase());
			const esMediaJornada = leg.jornada === "media_jornada";
			const basicoReferencia = catNueva ? catNueva.basico : Math.round(leg.sueldoBasico * factor);
			const nuevoSueldo = esMediaJornada && config.proporcionalMediaJornada ? Math.round(basicoReferencia / 2) : basicoReferencia;
			sueldosPrevios.push({
				legajoId: leg.id,
				nombre: leg.nombreCompleto,
				antes: leg.sueldoBasico,
				despues: nuevoSueldo
			});
			legajosAfectados++;
			return {
				...leg,
				sueldoBasico: nuevoSueldo,
				categoria: catNueva ? catNueva.nombre : leg.categoria
			};
		}),
		resultado: {
			convenioActualizado: nuevoConvenio,
			legajosAfectados,
			categoriasAfectadas: nuevasCategorias.length,
			sueldosPrevios
		}
	};
}
