	const calcularEstadoPeriodoPrueba = (fechaIngresoStr, mesesPrueba) => {
		try {
			const partes = fechaIngresoStr.split("/");
			if (partes.length !== 3) return {
				enPrueba: false,
				diasRestantes: 0
			};
			const dia = parseInt(partes[0], 10);
			const mes = parseInt(partes[1], 10) - 1;
			const anio = parseInt(partes[2], 10);
			const fechaIngreso = new Date(anio, mes, dia);
			const fechaFinPrueba = new Date(fechaIngreso);
			fechaFinPrueba.setMonth(fechaFinPrueba.getMonth() + mesesPrueba);
			const fechaHoy = new Date(2026, 9, 16);
			const diffTime = fechaFinPrueba.getTime() - fechaHoy.getTime();
			const diffDays = Math.ceil(diffTime / 864e5);
			return {
				enPrueba: diffDays > 0,
				diasRestantes: Math.max(0, diffDays),
				fechaFinPrueba: fechaFinPrueba.toLocaleDateString("es-AR")
			};
		} catch {
			return {
				enPrueba: false,
				diasRestantes: 0
			};
		}
	};
