		const horasExtras = novEmpleado.filter((n) => n.tipo === "horas_extras_50" || n.tipo === "horas_extras_100").reduce((acc, n) => acc + n.monto, 0);
		const comisiones = novEmpleado.filter((n) => n.tipo === "comision_ventas").reduce((acc, n) => acc + n.monto, 0);
		const adelantos = novEmpleado.filter((n) => n.tipo === "adelanto_sueldo").reduce((acc, n) => acc + n.monto, 0);
		let basicoLiquidado = emp.sueldoBasico;
