		const totalIndemnizatorio = indemnizacionAntiguedad + preavisoOmitido + integracionMes + vacacionesNoGozadas;
		const totalBruto = totalRemunerativo + totalNoRemunerativo + totalIndemnizatorio;
		const baseObraSocial = emp.jornada === "media_jornada" ? Math.max(totalRemunerativo * 2, totalRemunerativo) : totalRemunerativo;
		const jubilacion11 = totalRemunerativo * .11;
		const ley19032_3 = totalRemunerativo * .03;
		const obraSocial3 = baseObraSocial * .03;
		const sindicatoSec2 = emp.afiliadoSindicato ? totalRemunerativo * .02 : 0;
		const faecys05 = emp.convenio.includes("130/75") ? totalRemunerativo * .005 : 0;
